//! Golden-vector tests against the C reference implementation.
//!
//! `reference/golden.txt` is generated by `reference/c_golden.c`, a
//! verbatim transcription of the OpenNI 2.2.0 algorithm cores
//! (XnShiftToDepthUpdate and Unpack11to16). This test proves the Rust
//! ports produce identical output for the same inputs.

use xtion::depth::packed11::unpack_packed11_vec;
use xtion::depth::shift_to_depth::{ShiftToDepthConfig, ShiftToDepthTables};

const GOLDEN: &str = include_str!("../reference/golden.txt");

#[test]
fn shift_to_depth_matches_c_reference() {
    let mut lines = GOLDEN.lines();
    let mut configs = 0;

    while let Some(line) = lines.next() {
        let Some(rest) = line.strip_prefix("S2D ") else {
            continue;
        };
        // name zpd zpps lddis maxshift maxdepth constshift psf coeff scale mincut maxcut
        let f: Vec<&str> = rest.split_whitespace().collect();
        let config = ShiftToDepthConfig {
            zero_plane_distance: f[1].parse().unwrap(),
            zero_plane_pixel_size: f[2].parse().unwrap(),
            emitter_d_cmos_distance: f[3].parse().unwrap(),
            device_max_shift: f[4].parse().unwrap(),
            device_max_depth: f[5].parse().unwrap(),
            const_shift: f[6].parse().unwrap(),
            pixel_size_factor: f[7].parse().unwrap(),
            param_coeff: f[8].parse().unwrap(),
            shift_scale: f[9].parse().unwrap(),
            depth_min_cutoff: f[10].parse().unwrap(),
            depth_max_cutoff: f[11].parse().unwrap(),
        };
        let name = f[0];

        // the two table lines immediately follow the config line
        let s2d_line = lines.next().expect("S2D_TABLE after config");
        let d2s_line = lines.next().expect("D2S_TABLE after config");

        let parse_table = |line: &str, prefix: &str| -> Vec<u16> {
            line.strip_prefix(prefix)
                .expect("table line prefix")
                .split_whitespace()
                .map(|v| v.parse().unwrap())
                .collect()
        };
        let expected_s2d = parse_table(s2d_line, "S2D_TABLE");
        let expected_d2s = parse_table(d2s_line, "D2S_TABLE");

        let tables = ShiftToDepthTables::build(&config);
        configs += 1;
        assert_eq!(
            tables.shift_to_depth, expected_s2d,
            "s2d table mismatch for config {name}"
        );
        assert_eq!(
            tables.depth_to_shift, expected_d2s,
            "d2s table mismatch for config {name}"
        );
    }
    assert!(
        configs >= 2,
        "expected at least 2 S2D configs in golden file, found {configs}"
    );
}

#[test]
fn packed11_matches_c_reference() {
    let mut checked = 0usize;
    for line in GOLDEN.lines() {
        if !line.starts_with("P11 ") {
            continue;
        }
        let parts: Vec<&str> = line.split_whitespace().collect();
        assert_eq!(parts.len(), 1 + 11 + 8);
        let input: Vec<u8> = parts[1..12]
            .iter()
            .map(|v| u8::from_str_radix(v, 16).unwrap())
            .collect();
        let expected: Vec<u16> = parts[12..20].iter().map(|v| v.parse().unwrap()).collect();
        assert_eq!(unpack_packed11_vec(&input), expected);
        checked += 1;
    }
    assert!(
        checked >= 512,
        "expected 512 packed11 groups, checked {checked}"
    );
}
